/* ============================================================
   PATCH 1.0.19 — умолчание часов по норме дня
   Пн-Чт extended = 08:15, Пт extended = 07:45, legacy/выходной = 08:00
   ============================================================ */
(function(){
'use strict';
if (window.__trkHoursDefaultV1019) return;
window.__trkHoursDefaultV1019 = true;

function _getDayNorm(dk) {
    if (!dk) return 8;
    var st = window.__trkState || {};

    // 1. Из загруженного календаря (приоритет — там day_norm с учётом праздников)
    if (st.calendar && st.calendar.days) {
        for (var i = 0; i < st.calendar.days.length; i++) {
            var d = st.calendar.days[i];
            if (d && d.date === dk && typeof d.day_norm === 'number') {
                return d.day_norm;
            }
        }
    }

    // 2. Fallback: weekday + state.workSchedule
    try {
        var parts = String(dk).split('-');
        var y = parseInt(parts[0], 10);
        var m = parseInt(parts[1], 10);
        var dd = parseInt(parts[2], 10);
        var dt = new Date(y, m - 1, dd);
        var wd = dt.getDay(); // 0=Вс, 1=Пн, ..., 6=Сб
        if (wd === 0 || wd === 6) return 0;
        var mode = st.workSchedule || 'legacy';
        if (mode === 'extended') {
            return wd === 5 ? 7.75 : 8.25; // Пт=7.75, Пн-Чт=8.25
        }
        return 8;
    } catch (e) {
        return 8;
    }
}

function _fmt(h) {
    if (typeof window._formatHoursInput === 'function') {
        return window._formatHoursInput(h);
    }
    // 1.0.18 не применился — показываем как число
    var v = Number(h) || 0;
    if (v === Math.floor(v)) return String(v);
    return String(v);
}

function _applyDefaultHours() {
    var lh = document.getElementById('log_hours');
    if (!lh) return;
    var lid = document.getElementById('log_id');
    // Не трогаем при редактировании
    if (lid && lid.value) return;
    // Не трогаем, если пользователь уже менял поле в этой сессии
    if (lh._userTouchedHours) return;

    var ldt = document.getElementById('log_date');
    var dk = ldt ? ldt.value : '';
    var norm = _getDayNorm(dk);
    // На выходных/праздниках (norm=0) оставляем 8, как было раньше
    var useVal = norm > 0 ? norm : 8;
    lh.value = _fmt(useVal);
}

// Отслеживание «пользователь трогал поле»
document.addEventListener('input', function(e){
    if (e.target && e.target.id === 'log_hours') {
        e.target._userTouchedHours = true;
    }
}, true);

// При открытии модалки — сбрасываем «touch» и ставим норму
(function _watchOpen(){
    var lm = document.getElementById('logModal');
    if (!lm || lm._hoursDefaultV1019) return;
    lm._hoursDefaultV1019 = true;
    new MutationObserver(function(){
        if (lm.classList.contains('active')) {
            var lh = document.getElementById('log_hours');
            if (lh) lh._userTouchedHours = false;
            setTimeout(_applyDefaultHours, 30);
            setTimeout(_applyDefaultHours, 150);
            setTimeout(_applyDefaultHours, 400);
        }
    }).observe(lm, { attributes: true, attributeFilter: ['class'] });
})();

// При смене даты — пересчитываем, только если поле не тронуто
document.addEventListener('change', function(e){
    if (!e.target || e.target.id !== 'log_date') return;
    setTimeout(_applyDefaultHours, 30);
    setTimeout(_applyDefaultHours, 150);
}, true);

// На случай, если модалка уже открыта при загрузке
setTimeout(_applyDefaultHours, 800);

window.__trkApplyHoursDefault = _applyDefaultHours;
window.__trkGetDayNorm = _getDayNorm;

})();
